import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits (0 <= k <= 7).

    Bits shifted out of the high end wrap around to the low end.
    x must be in 0..255 and k in 0..7. The result is in 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_zero_shift_is_identity() -> None:
    for x in range(256):
        assert rotl8(x, 0) == x


def test_rotl8_single_bit_wraps_to_low_end() -> None:
    assert rotl8(0b1000_0001, 1) == 0b0000_0011


def test_rotl8_high_bit_moves_to_bit_zero() -> None:
    assert rotl8(0x80, 1) == 0x01


def test_rotl8_seven_bits_from_lowest() -> None:
    assert rotl8(0x01, 7) == 0x80


def test_rotl8_nibble_swap() -> None:
    assert rotl8(0xAB, 4) == 0xBA


@pytest.mark.parametrize(
    ("x", "k", "expected"),
    [
        (0x00, 3, 0x00),
        (0xFF, 5, 0xFF),
        (0x12, 1, 0x24),
        (0x96, 2, 0x5A),
    ],
)
def test_rotl8_examples(x: int, k: int, expected: int) -> None:
    assert rotl8(x, k) == expected


def test_rotl8_result_stays_in_byte_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_composition_adds_shifts_mod_8() -> None:
    for x in range(256):
        for a in range(8):
            for b in range(8):
                assert rotl8(rotl8(x, a), b) == rotl8(x, (a + b) % 8)
